/* Community analytics tracking (round 37), run after part 184. A community's Analytics now counts by the hour, so every day of its chart starts at midnight in the viewer's own time zone, not at midnight in London. The nightly count keeps each hour's visitors and visitors who were not members in the new server only table `community_visit_hours` (the community, the hour, two counts; nothing about a visitor), and this part fills it from the visits still kept (the last three days). A member who opens their community or does anything in it is now also written once an hour to the new server only table `community_member_hours` (the community, the member, the hour), beside the day row part 184 writes, so active members are counted by the viewer's own days, and by the hour too. `community_analytics` is replaced, with the same arguments and the same answer: members who took part are now read from the posts, comments and reactions themselves (a like on one's own post was left out before), a post or comment the safety check held back is not counted as one, active members come from the hours once they are kept (the days before that from part 184's days), and a new `joined_by_visit` counts the joins a visitor made themselves (free, paid, bought or by invite; not those added by the team, by Storelib or by owning a product), which is what the join rate divides. No existing rows change. Until it runs, Analytics counts as part 184 does. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_visit_hours (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, hour timestamptz NOT NULL, visitors integer NOT NULL DEFAULT 0, prospects integer NOT NULL DEFAULT 0, CONSTRAINT community_visit_hours_pkey PRIMARY KEY (community_id, hour), CONSTRAINT community_visit_hours_counts_check CHECK (visitors >= 0 AND prospects >= 0 AND prospects <= visitors));
ALTER TABLE public.community_visit_hours ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_visit_hours FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_visit_hours TO service_role;
CREATE TABLE IF NOT EXISTS public.community_member_hours (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, hour timestamptz NOT NULL, CONSTRAINT community_member_hours_pkey PRIMARY KEY (community_id, hour, user_id));
ALTER TABLE public.community_member_hours ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_member_hours FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, DELETE ON public.community_member_hours TO service_role;
CREATE INDEX IF NOT EXISTS community_member_hours_user_idx ON public.community_member_hours (community_id, user_id, hour);
DO $do$ BEGIN IF to_regclass('public.community_view_days') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_view_days' AND column_name = 'member') THEN RAISE NOTICE 'community analytics tracking: community_view_days has no member column, run part 184 first. Nothing to fill.'; RETURN; END IF; INSERT INTO public.community_visit_hours (community_id, hour, visitors, prospects) SELECT v.community_id, date_trunc('hour', v.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC', count(*)::int, (count(*) FILTER (WHERE v.member IS NOT TRUE))::int FROM public.community_view_days v WHERE v.day < (now() AT TIME ZONE 'UTC')::date GROUP BY 1, 2 ON CONFLICT (community_id, hour) DO UPDATE SET visitors = excluded.visitors, prospects = excluded.prospects; END $do$;
CREATE OR REPLACE FUNCTION public.community_analytics(p_community uuid, p_from timestamptz, p_to timestamptz, p_tz text DEFAULT 'UTC', p_grain text DEFAULT 'day', p_detail boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ DECLARE v_tz text := 'UTC'; v_grain text := 'day'; v_fmt text; v_owner uuid; v_out jsonb; v_detail jsonb := '{}'::jsonb; v_end_month date; v_first_hour timestamptz; v_cut timestamptz; v_cut_day date; BEGIN IF p_community IS NULL OR p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '800 days' THEN RETURN NULL; END IF; BEGIN IF p_tz IS NOT NULL AND length(p_tz) BETWEEN 1 AND 64 THEN PERFORM now() AT TIME ZONE p_tz; v_tz := p_tz; END IF; EXCEPTION WHEN others THEN v_tz := 'UTC'; END; IF p_grain IN ('hour', 'day', 'month') THEN v_grain := p_grain; END IF; v_fmt := CASE v_grain WHEN 'hour' THEN 'YYYY-MM-DD"T"HH24' WHEN 'day' THEN 'YYYY-MM-DD' ELSE 'YYYY-MM' END; SELECT owner_user_id INTO v_owner FROM public.communities WHERE id = p_community; SELECT min(hour) INTO v_first_hour FROM public.community_member_hours WHERE community_id = p_community; IF v_first_hour IS NOT NULL THEN v_cut_day := (v_first_hour AT TIME ZONE 'UTC')::date + 1; v_cut := v_cut_day::timestamp AT TIME ZONE 'UTC'; END IF; WITH act AS (SELECT kind, user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_activity WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND kind IN ('joined', 'left', 'lesson_completed', 'course_completed')), joins AS (SELECT a.b FROM act a LEFT JOIN public.community_members m ON m.community_id = p_community AND m.user_id = a.user_id WHERE a.kind = 'joined' AND a.user_id IS DISTINCT FROM v_owner AND coalesce(m.source, 'free') NOT IN ('manual', 'platform', 'product', 'owner')), posts AS (SELECT author_id AS user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_posts WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND NOT (status = 'removed' AND coalesce(removed_reason, '') LIKE 'Held for review:%')), comments AS (SELECT author_id AS user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_feed_comments WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to AND NOT (status = 'removed' AND coalesce(removed_reason, '') LIKE 'Held for review:%')), reactions AS (SELECT user_id, to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_reactions WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), took AS (SELECT user_id, b, 'post' AS k FROM posts WHERE user_id IS NOT NULL UNION ALL SELECT user_id, b, 'comment' FROM comments WHERE user_id IS NOT NULL UNION ALL SELECT user_id, b, 'reaction' FROM reactions WHERE user_id IS NOT NULL), rsvps AS (SELECT to_char(created_at AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_event_rsvps WHERE community_id = p_community AND created_at >= p_from AND created_at < p_to), hours AS (SELECT user_id, to_char(hour AT TIME ZONE v_tz, v_fmt) AS b FROM public.community_member_hours WHERE community_id = p_community AND v_cut IS NOT NULL AND hour >= greatest(p_from, v_cut) AND hour < p_to), days AS (SELECT user_id, CASE v_grain WHEN 'month' THEN to_char(day, 'YYYY-MM') ELSE to_char(day, 'YYYY-MM-DD') END AS b FROM public.community_member_days WHERE community_id = p_community AND day >= (p_from AT TIME ZONE v_tz)::date AND day <= ((p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date AND (v_cut_day IS NULL OR day < v_cut_day)), here AS (SELECT user_id, b FROM hours UNION ALL SELECT user_id, b FROM days WHERE v_grain <> 'hour') SELECT jsonb_build_object('joined', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'joined' AND user_id IS DISTINCT FROM v_owner GROUP BY b) x), 'joined_by_visit', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM joins GROUP BY b) x), 'left', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'left' GROUP BY b) x), 'posts', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM posts GROUP BY b) x), 'comments', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM comments GROUP BY b) x), 'reactions', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM reactions GROUP BY b) x), 'rsvps', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM rsvps GROUP BY b) x), 'lessons', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(*) AS n FROM act WHERE kind = 'lesson_completed' GROUP BY b) x), 'contributors', (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM took GROUP BY b) x), 'active', CASE WHEN v_grain = 'hour' AND (v_cut IS NULL OR v_cut > p_from) THEN NULL ELSE (SELECT coalesce(jsonb_object_agg(b, n), '{}'::jsonb) FROM (SELECT b, count(DISTINCT user_id) AS n FROM here GROUP BY b) x) END, 'totals', jsonb_build_object('contributors', (SELECT count(DISTINCT user_id) FROM took), 'posters', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'post'), 'commenters', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'comment'), 'reactors', (SELECT count(DISTINCT user_id) FROM took WHERE k = 'reaction'), 'active', (SELECT count(DISTINCT user_id) FROM (SELECT user_id FROM hours UNION SELECT user_id FROM days) u), 'courses', (SELECT count(*) FROM act WHERE kind = 'course_completed')), 'active_since', (SELECT min(day) FROM public.community_member_days WHERE community_id = p_community), 'active_hours_since', v_cut) INTO v_out; IF p_detail THEN v_end_month := date_trunc('month', (p_to - interval '1 microsecond') AT TIME ZONE v_tz)::date; v_detail := jsonb_build_object('top_contributors', (SELECT coalesce(jsonb_agg(x ORDER BY x.score DESC, x.user_id), '[]'::jsonb) FROM (SELECT u.user_id, sum(u.posts)::int AS posts, sum(u.comments)::int AS comments, sum(u.posts) * 2 + sum(u.comments) AS score FROM (SELECT author_id AS user_id, 1 AS posts, 0 AS comments FROM public.community_feed_posts WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to UNION ALL SELECT author_id, 0, 1 FROM public.community_feed_comments WHERE community_id = p_community AND status = 'published' AND author_id IS NOT NULL AND created_at >= p_from AND created_at < p_to) u GROUP BY u.user_id ORDER BY score DESC, u.user_id LIMIT 10) x), 'top_spaces', (SELECT coalesce(jsonb_agg(x ORDER BY (x.posts + x.comments) DESC, x.name), '[]'::jsonb) FROM (SELECT s.id, s.name, s.slug, (SELECT count(*) FROM public.community_feed_posts p WHERE p.space_id = s.id AND p.status = 'published' AND p.created_at >= p_from AND p.created_at < p_to)::int AS posts, (SELECT count(*) FROM public.community_feed_comments c JOIN public.community_feed_posts p ON p.id = c.post_id WHERE p.space_id = s.id AND c.status = 'published' AND c.created_at >= p_from AND c.created_at < p_to)::int AS comments FROM public.community_spaces s WHERE s.community_id = p_community AND s.archived_at IS NULL) x WHERE x.posts + x.comments > 0), 'cohorts', (SELECT coalesce(jsonb_agg(x ORDER BY x.month DESC), '[]'::jsonb) FROM (SELECT to_char(date_trunc('month', m.joined_at AT TIME ZONE v_tz), 'YYYY-MM') AS month, count(*)::int AS joined, count(*) FILTER (WHERE m.status = 'active')::int AS stayed, count(*) FILTER (WHERE m.status = 'active' AND greatest(m.last_seen_at, m.last_active_at) >= now() - interval '30 days')::int AS active FROM public.community_members m WHERE m.community_id = p_community AND m.role <> 'owner' AND m.joined_at IS NOT NULL AND m.joined_at AT TIME ZONE v_tz >= (v_end_month - interval '5 months') AND m.joined_at AT TIME ZONE v_tz < (v_end_month + interval '1 month') GROUP BY 1) x), 'programs', (SELECT coalesce(jsonb_agg(x ORDER BY x.started DESC, x.title), '[]'::jsonb) FROM (SELECT cc.id, coalesce(nullif(cc.title, ''), pr.title, 'Program') AS title, count(e.id)::int AS started, count(e.completed_at)::int AS completed, coalesce(round(avg(e.percent))::int, 0) AS percent, (SELECT count(*) FROM public.community_activity a WHERE a.community_id = p_community AND a.kind = 'lesson_completed' AND a.created_at >= p_from AND a.created_at < p_to AND a.target_id IN (cc.id::text, cc.product_id::text))::int AS lessons FROM public.community_courses cc LEFT JOIN public.products pr ON pr.id = cc.product_id LEFT JOIN public.courses co ON co.id = coalesce(cc.course_id, (SELECT c2.id FROM public.courses c2 WHERE c2.product_id = cc.product_id ORDER BY c2.created_at LIMIT 1)) LEFT JOIN public.course_enrollments e ON e.course_id = co.id AND EXISTS (SELECT 1 FROM public.community_members m WHERE m.community_id = p_community AND m.user_id = e.buyer_id AND m.status = 'active') WHERE cc.community_id = p_community AND coalesce(cc.status, 'published') = 'published' GROUP BY cc.id, cc.title, pr.title, cc.product_id LIMIT 20) x)); END IF; RETURN v_out || v_detail; END $f$;
REVOKE ALL ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_analytics(uuid, timestamptz, timestamptz, text, text, boolean) TO service_role;
notify pgrst, 'reload schema';
